    WHEN 'pos_store_settings' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_pos_store_settings(v_rows)+public.sync_delete_pos_store_settings(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'settings_scoped' THEN IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r WHERE lower(COALESCE(r->>'scope','')) NOT IN ('global','cluster','branch','terminal')) THEN RAISE EXCEPTION 'SYNC_SCOPE_FORBIDDEN'; END IF; SELECT COALESCE(jsonb_agg(r) FILTER (WHERE (lower(COALESCE(r->>'scope',''))='global' AND r->>'scope_id'='' AND r->>'key' LIKE 'pos_field:%' AND auth.role()='service_role') OR (lower(COALESCE(r->>'scope',''))='branch' AND r->>'scope_id'=p_branch_id) OR (lower(COALESCE(r->>'scope',''))='terminal' AND r->>'scope_id'=p_terminal_id)),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r; v_count:=public.sync_apply_settings_scoped(v_rows)+public.sync_delete_settings_scoped(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'stock_count_drafts' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_stock_count_drafts(v_rows)+public.sync_delete_stock_count_drafts(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'authorization_actions' THEN  v_count:=public.sync_apply_authorization_actions(v_rows)+public.sync_delete_authorization_actions(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'authorization_action_history' THEN  v_count:=public.sync_apply_authorization_action_history(v_rows)+public.sync_delete_authorization_action_history(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'authorization_requests' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_authorization_requests(v_rows)+public.sync_delete_authorization_requests(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'authorization_log' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_authorization_log(v_rows)+public.sync_delete_authorization_log(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'record_edits' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_record_edits(v_rows)+public.sync_delete_record_edits(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'shift_cash_counts' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_shift_cash_counts(v_rows)+public.sync_delete_shift_cash_counts(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'shift_close_events' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_shift_close_events(v_rows)+public.sync_delete_shift_close_events(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'shift_reconciliations' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_shift_reconciliations(v_rows)+public.sync_delete_shift_reconciliations(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'shift_variance_alerts' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_shift_variance_alerts(v_rows)+public.sync_delete_shift_variance_alerts(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'shift_notifications' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_shift_notifications(v_rows)+public.sync_delete_shift_notifications(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'entity_status_history' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO v_rows FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_entity_status_history(v_rows)+public.sync_delete_entity_status_history(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'nav_pins' THEN  v_count:=public.sync_apply_nav_pins(v_rows)+public.sync_delete_nav_pins(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'store_groups' THEN  v_count:=public.sync_apply_store_groups(v_rows)+public.sync_delete_store_groups(v_op->'changes',p_branch_id,p_terminal_id);
    WHEN 'change_history' THEN  v_count:=public.sync_apply_change_history(v_rows)+public.sync_delete_change_history(v_op->'changes',p_branch_id,p_terminal_id); ELSE RAISE EXCEPTION 'SYNC_TABLE_FORBIDDEN'; END CASE; v_total:=v_total+v_count;
 END LOOP;
 INSERT INTO public.sync_idempotency_receipts(batch_id,organization_id,branch_id,table_name,payload_hash,applied_count) VALUES(p_batch_id,p_organization_id,p_branch_id,'__aggregate__',v_hash,v_total);
 RETURN jsonb_build_object('ok',true,'applied',v_total,'batch_id',p_batch_id)||public.pos_sync_aggregate_shift_closure_ack(p_operations,p_branch_id);
END $function$

CREATE OR REPLACE FUNCTION public.pos_sync_push_author_shift_intent(p_batch_id uuid, p_organization_id text, p_branch_id text, p_terminal_id text, p_operations jsonb, p_shift_intent jsonb, p_shift_author jsonb, p_author_authority jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE intent jsonb; receipt pos_sync_private.shift_intent_receipts%ROWTYPE; historical pos_sync_private.shift_author_receipts%ROWTYPE;
 registered pos_sync_private.shift_author_keys%ROWTYPE; person public.app_users%ROWTYPE;
 hash text; v_shift uuid; action text; result jsonb; op jsonb; proposed jsonb; old jsonb; authorized boolean; previous_proof text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'SYNC_FORBIDDEN'; END IF;
 PERFORM public.pos_sync_validate_scope(p_organization_id,p_branch_id,p_terminal_id);
 IF p_shift_intent->>'payloadJson' IS NULL OR octet_length(convert_to(p_shift_intent->>'payloadJson','UTF8'))>6*1024*1024 THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_INVALID'; END IF;
 intent:=(p_shift_intent->>'payloadJson')::jsonb; hash:=encode(sha256(convert_to(p_shift_intent->>'payloadJson','UTF8')),'hex');
 v_shift:=(intent->>'shiftId')::uuid; action:=intent->>'kind';
 IF p_shift_author->'version' IS DISTINCT FROM '1'::jsonb OR p_shift_author->>'algorithm' IS DISTINCT FROM 'Ed25519' OR
   p_shift_author->>'terminalId' IS DISTINCT FROM p_terminal_id OR lower(btrim(p_shift_author->>'branchId')) IS DISTINCT FROM lower(btrim(p_branch_id)) OR
   (p_shift_author->>'shiftId')::uuid IS DISTINCT FROM v_shift OR (p_shift_author->>'intentId')::uuid IS DISTINCT FROM p_batch_id OR
   p_shift_author->>'action' IS DISTINCT FROM action OR p_shift_author->>'payloadHash' IS DISTINCT FROM hash
 THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_INVALID'; END IF;
 SELECT * INTO registered FROM pos_sync_private.shift_author_keys WHERE key_id=(p_shift_author->>'keyId')::uuid AND author_id=(p_shift_author->>'authorId')::uuid
  AND terminal_id=p_terminal_id AND project_origin=p_shift_author->>'projectOrigin' AND subject=p_shift_author->>'subject' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_INVALID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-batch:'||p_batch_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-intent:'||p_batch_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-shift:'||v_shift::text,0));
 IF EXISTS(SELECT 1 FROM pos_sync_private.shift_closing_start_receipts s WHERE s.intent_id=p_batch_id AND s.proof IS DISTINCT FROM NULLIF(current_setting('pos.shift_closing_start',true),'')::jsonb->'proof') THEN RAISE EXCEPTION 'SYNC_SHIFT_START_HISTORY_UNPROVEN'; END IF;
 SELECT * INTO receipt FROM pos_sync_private.shift_intent_receipts WHERE intent_id=p_batch_id;
 IF FOUND THEN
  SELECT * INTO historical FROM pos_sync_private.shift_author_receipts WHERE intent_id=p_batch_id;
  IF NOT FOUND OR historical.attestation IS DISTINCT FROM p_shift_author OR
    ROW(receipt.branch_id,receipt.terminal_id,receipt.shift_id,receipt.payload_hash) IS DISTINCT FROM ROW(p_branch_id,p_terminal_id,v_shift,hash)
  THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_HISTORY_UNPROVEN'; END IF;
  previous_proof:=current_setting('pos.shift_author',true);PERFORM set_config('pos.shift_author',p_shift_author::text,true);
  result:=public.pos_sync_push_shift_intent(p_batch_id,p_organization_id,p_branch_id,p_terminal_id,p_operations,p_shift_intent);
  PERFORM set_config('pos.shift_author',COALESCE(previous_proof,''),true);
  RETURN result;
 END IF;
 -- Only NEW writes reach this point. Row locks make a concurrent key/account/
 -- permission revocation wait for this transaction, without locking sales.
 IF p_author_authority->'allowed' IS DISTINCT FROM 'true'::jsonb OR p_author_authority->'authority'->>'authorId' IS DISTINCT FROM registered.author_id::text OR registered.revoked_at IS NOT NULL
 THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_PERMISSION_REVOKED'; END IF;
 SELECT * INTO person FROM public.app_users WHERE id=registered.author_id FOR SHARE;
 IF NOT FOUND OR person.is_active IS DISTINCT FROM true OR person.user_id IS DISTINCT FROM registered.subject OR
   (person.store_id IS NOT NULL AND lower(btrim(person.store_id)) IS DISTINCT FROM lower(btrim(p_branch_id)))
 THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_PERMISSION_REVOKED'; END IF;
 IF EXISTS(SELECT 1 FROM public.terminal_tokens WHERE id::text=p_terminal_id AND location_id IS NULL) AND
   NOT pos_sync_private.shift_author_management_allowed(person.role::text,person.role_slug,person.permissions)
 THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_PERMISSION_REVOKED'; END IF;
 authorized:=CASE action WHEN 'ORIGINAL' THEN pos_sync_private.shift_author_flag(person.permissions,'can_shift_cash_count') OR pos_sync_private.shift_author_flag(person.permissions,'can_close_shift')
  WHEN 'RECOUNT' THEN pos_sync_private.shift_author_flag(person.permissions,'can_shift_cash_recount')
  WHEN 'VARIANCE' THEN pos_sync_private.shift_author_flag(person.permissions,'can_shift_variance_approve') ELSE false END;
 IF NOT COALESCE(authorized,false) THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_PERMISSION_REVOKED'; END IF;
 FOR op IN SELECT value FROM jsonb_array_elements(intent->'operations') LOOP
  IF action='ORIGINAL' AND op->>'table'='shifts' AND EXISTS(SELECT 1 FROM jsonb_array_elements(op->'rows') p WHERE p->>'closed_by_staff_id' IS DISTINCT FROM registered.subject OR p->>'closed_by_name' IS DISTINCT FROM registered.subject)
  THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_ACTOR_MISMATCH'; END IF;
  IF op->>'table'='activity_events' AND EXISTS(SELECT 1 FROM jsonb_array_elements(op->'rows') p WHERE p->>'actor_name' IS DISTINCT FROM registered.subject AND NOT EXISTS(SELECT 1 FROM public.activity_events a WHERE a.id=(p->>'id')::uuid))
  THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_ACTOR_MISMATCH'; END IF;
  IF op->>'table'=ANY(ARRAY['shift_cash_counts','shift_close_events']) THEN
   FOR proposed IN SELECT value FROM jsonb_array_elements(op->'rows') LOOP
    EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE id=$1',op->>'table') INTO old USING (proposed->>'id')::uuid;
    IF old IS NOT NULL THEN CONTINUE; END IF;
    IF op->>'table'='shift_cash_counts' AND (proposed->>'counted_by_staff_id' IS DISTINCT FROM registered.subject OR proposed->>'counted_by_name' IS DISTINCT FROM registered.subject OR
      proposed->>'kind' IS DISTINCT FROM CASE action WHEN 'ORIGINAL' THEN 'ORIGINAL' WHEN 'RECOUNT' THEN 'RECOUNT' ELSE '' END) THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_ACTOR_MISMATCH'; END IF;
    IF op->>'table'='shift_close_events' AND ((NOT (action='ORIGINAL' AND proposed->>'event'='closing_started' AND pos_sync_private.proven_closing_start(p_batch_id,proposed)) AND (proposed->>'actor_staff_id' IS DISTINCT FROM registered.subject OR proposed->>'actor_name' IS DISTINCT FROM registered.subject)) OR
      (action='ORIGINAL' AND NOT COALESCE(proposed->>'event'=ANY(ARRAY['closing_started','cash_count_submitted','reconciled']),false)) OR (action='RECOUNT' AND proposed->>'event' IS DISTINCT FROM 'recount_submitted') OR (action='VARIANCE' AND proposed->>'event' IS DISTINCT FROM 'variance_approved'))
    THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_ACTOR_MISMATCH'; END IF;
    -- A locally saved start may first reach the server in the signed ORIGINAL
    -- graph. It must belong to this same author and the exact parent start;
    -- another person's unuploaded history requires separate proven provenance.
    IF op->>'table'='shift_close_events' AND proposed->>'event'='closing_started' AND (
      proposed->>'from_state' IS DISTINCT FROM 'ACTIVE' OR proposed->>'to_state' IS DISTINCT FROM 'CASH_COUNT_REQUIRED' OR
      proposed->>'shift_id' IS DISTINCT FROM v_shift::text OR proposed->>'store_id' IS DISTINCT FROM p_branch_id OR
      proposed->>'terminal_id' IS DISTINCT FROM p_terminal_id OR proposed->>'created_at' IS NULL OR
      NOT EXISTS(SELECT 1 FROM jsonb_array_elements(intent->'operations') parent_op,
        LATERAL jsonb_array_elements(parent_op->'rows') parent
        WHERE parent_op->>'table'='shifts' AND parent->>'id'=v_shift::text AND parent->>'store_id'=p_branch_id AND (parent->>'terminal_id'=p_terminal_id OR (action='ORIGINAL' AND pos_sync_private.proven_closing_start(p_batch_id,proposed)))
          AND parent->>'closing_started_by'=CASE WHEN pos_sync_private.proven_closing_start(p_batch_id,proposed) THEN proposed->>'actor_staff_id' ELSE registered.subject END
          AND (parent->>'closing_started_at')::timestamptz=(proposed->>'created_at')::timestamptz
          AND parent->>'close_reason'=proposed->'detail'->>'reason'))
    THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_ACTOR_MISMATCH'; END IF;
   END LOOP;
  END IF;
 END LOOP;
 previous_proof:=current_setting('pos.shift_author',true);
 PERFORM set_config('pos.shift_author',p_shift_author::text,true);
 result:=public.pos_sync_push_shift_intent(p_batch_id,p_organization_id,p_branch_id,p_terminal_id,p_operations,p_shift_intent);
 PERFORM set_config('pos.shift_author',COALESCE(previous_proof,''),true);
 INSERT INTO pos_sync_private.shift_author_receipts(intent_id,shift_id,terminal_id,branch_id,key_id,author_id,attestation)
 VALUES(p_batch_id,v_shift,p_terminal_id,p_branch_id,registered.key_id,registered.author_id,p_shift_author);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.pos_sync_push_batch(p_batch_id uuid, p_organization_id text, p_branch_id text, p_table text, p_rows jsonb, p_changes jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me public.app_users%ROWTYPE; v_count integer:=0; v_hash text:=md5(p_table||COALESCE(p_rows,'[]'::jsonb)::text||COALESCE(p_changes,'[]'::jsonb)::text); v_prior text;
BEGIN
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('pos-sync-batch:' || p_batch_id::text, 0));
 IF auth.role()<>'service_role' THEN
  SELECT * INTO v_me FROM public.app_users WHERE auth_user_id=auth.uid() AND is_active=true LIMIT 1;
  IF v_me.id IS NULL OR NOT (v_me.role='admin' OR COALESCE((v_me.permissions->>'can_manage_sync_backup')::boolean,false)) THEN RAISE EXCEPTION 'SYNC_FORBIDDEN'; END IF;
  IF NOT (v_me.role='admin' OR v_me.store_id IS NULL OR v_me.store_id=p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF;
 END IF;
 SELECT payload_hash INTO v_prior FROM public.sync_idempotency_receipts WHERE batch_id=p_batch_id;
 IF FOUND THEN IF v_prior<>v_hash THEN RAISE EXCEPTION 'SYNC_IDEMPOTENCY_MISMATCH'; END IF; RETURN jsonb_build_object('ok',true,'replayed',true,'batch_id',p_batch_id); END IF;
 CASE p_table WHEN 'coupon_campaigns' THEN  v_count:=public.sync_apply_coupon_campaigns(p_rows)+public.sync_delete_coupon_campaigns(p_changes,p_branch_id);
    WHEN 'shifts' THEN IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_shifts(p_rows)+public.sync_delete_shifts(p_changes,p_branch_id);
    WHEN 'issued_vouchers' THEN IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_issued_vouchers(p_rows)+public.sync_delete_issued_vouchers(p_changes,p_branch_id);
    WHEN 'activity_events' THEN IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_activity_events(p_rows)+public.sync_delete_activity_events(p_changes,p_branch_id);
