    WHEN 'authorization_requests' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO p_rows FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_authorization_requests(p_rows)+public.sync_delete_authorization_requests(p_changes,p_branch_id,p_terminal_id);
    WHEN 'authorization_log' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO p_rows FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_authorization_log(p_rows)+public.sync_delete_authorization_log(p_changes,p_branch_id,p_terminal_id);
    WHEN 'record_edits' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO p_rows FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_record_edits(p_rows)+public.sync_delete_record_edits(p_changes,p_branch_id,p_terminal_id);
    WHEN 'shift_cash_counts' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO p_rows FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_shift_cash_counts(p_rows)+public.sync_delete_shift_cash_counts(p_changes,p_branch_id,p_terminal_id);
    WHEN 'shift_close_events' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO p_rows FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_shift_close_events(p_rows)+public.sync_delete_shift_close_events(p_changes,p_branch_id,p_terminal_id);
    WHEN 'shift_reconciliations' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO p_rows FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_shift_reconciliations(p_rows)+public.sync_delete_shift_reconciliations(p_changes,p_branch_id,p_terminal_id);
    WHEN 'shift_variance_alerts' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO p_rows FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_shift_variance_alerts(p_rows)+public.sync_delete_shift_variance_alerts(p_changes,p_branch_id,p_terminal_id);
    WHEN 'shift_notifications' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO p_rows FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_shift_notifications(p_rows)+public.sync_delete_shift_notifications(p_changes,p_branch_id,p_terminal_id);
    WHEN 'entity_status_history' THEN SELECT COALESCE(jsonb_agg(CASE WHEN NULLIF(btrim(r->>'store_id'),'') IS NULL OR lower(btrim(r->>'store_id'))=lower(btrim(p_branch_id)) THEN r||jsonb_build_object('store_id',p_branch_id) ELSE r END),'[]'::jsonb) INTO p_rows FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows,'[]'::jsonb)) r WHERE r->>'store_id' IS NULL OR r->>'store_id'<>p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; v_count:=public.sync_apply_entity_status_history(p_rows)+public.sync_delete_entity_status_history(p_changes,p_branch_id,p_terminal_id);
    WHEN 'nav_pins' THEN  v_count:=public.sync_apply_nav_pins(p_rows)+public.sync_delete_nav_pins(p_changes,p_branch_id,p_terminal_id);
    WHEN 'store_groups' THEN  v_count:=public.sync_apply_store_groups(p_rows)+public.sync_delete_store_groups(p_changes,p_branch_id,p_terminal_id);
    WHEN 'change_history' THEN  v_count:=public.sync_apply_change_history(p_rows)+public.sync_delete_change_history(p_changes,p_branch_id,p_terminal_id); ELSE RAISE EXCEPTION 'SYNC_TABLE_FORBIDDEN'; END CASE;
 INSERT INTO public.sync_idempotency_receipts(batch_id,organization_id,branch_id,table_name,payload_hash,applied_count) VALUES(p_batch_id,p_organization_id,p_branch_id,p_table,v_hash,v_count);
 RETURN jsonb_build_object('ok',true,'applied',v_count,'batch_id',p_batch_id)||CASE WHEN p_table='shifts' THEN public.pos_sync_shift_closure_ack(p_rows,p_branch_id) ELSE '{}'::jsonb END;
END $function$

CREATE OR REPLACE FUNCTION public.pos_sync_push_started_shift_intent(p_batch_id uuid, p_organization_id text, p_branch_id text, p_terminal_id text, p_operations jsonb, p_shift_intent jsonb, p_shift_author jsonb, p_author_authority jsonb, p_closing_start jsonb, p_start_authority jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE raw text; payload jsonb; intent jsonb; parent jsonb; event_row jsonb; final_parent jsonb; old_event jsonb;
 registered pos_sync_private.shift_author_keys%ROWTYPE; person public.app_users%ROWTYPE; existing pos_sync_private.shift_closing_start_receipts%ROWTYPE;
 cloud_parent public.shifts%ROWTYPE; previous_context text; result jsonb; field text; v_shift uuid; event_count integer;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'SYNC_FORBIDDEN'; END IF;
 PERFORM public.pos_sync_validate_scope(p_organization_id,p_branch_id,p_terminal_id);
 IF jsonb_typeof(p_closing_start) IS DISTINCT FROM 'object' OR
    (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_closing_start) key) IS DISTINCT FROM
    ARRAY['algorithm','authorId','branchId','eventId','keyId','payloadHash','payloadJson','projectOrigin','shiftId','signature','subject','terminalId','version']::text[]
 THEN RAISE EXCEPTION 'SYNC_SHIFT_START_INVALID'; END IF;
 raw:=p_closing_start->>'payloadJson';
 IF raw IS NULL OR octet_length(convert_to(raw,'UTF8'))>16384 OR p_closing_start->'version' IS DISTINCT FROM '1'::jsonb OR
    p_closing_start->>'algorithm' IS DISTINCT FROM 'Ed25519' OR p_closing_start->>'signature' !~ '^[A-Za-z0-9_-]{86}$' OR
    p_closing_start->>'payloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex')
 THEN RAISE EXCEPTION 'SYNC_SHIFT_START_INVALID'; END IF;
 payload:=raw::jsonb; parent:=payload->'parent'; event_row:=payload->'event'; intent:=(p_shift_intent->>'payloadJson')::jsonb; v_shift:=(intent->>'shiftId')::uuid;
 IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(payload) key) IS DISTINCT FROM ARRAY['branchId','event','eventId','parent','shiftId','version']::text[] OR
    (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(parent) key) IS DISTINCT FROM ARRAY['close_reason','closing_started_at','closing_started_by','id','opened_at','opened_by_name','opened_by_staff_id','store_id','terminal_id']::text[] OR
    payload->'version' IS DISTINCT FROM '1'::jsonb OR intent->>'kind' IS DISTINCT FROM 'ORIGINAL' OR
    p_closing_start->>'projectOrigin' IS DISTINCT FROM p_shift_author->>'projectOrigin' OR p_closing_start->>'terminalId' IS DISTINCT FROM p_terminal_id OR
    lower(btrim(p_closing_start->>'branchId')) IS DISTINCT FROM lower(btrim(p_branch_id)) OR
    payload->>'branchId' IS DISTINCT FROM p_closing_start->>'branchId' OR (payload->>'shiftId')::uuid IS DISTINCT FROM v_shift OR
    (p_closing_start->>'shiftId')::uuid IS DISTINCT FROM v_shift OR (payload->>'eventId')::uuid IS DISTINCT FROM (p_closing_start->>'eventId')::uuid
 THEN RAISE EXCEPTION 'SYNC_SHIFT_START_INVALID'; END IF;
 IF jsonb_typeof(event_row) IS DISTINCT FROM 'object' OR event_row ?| ARRAY['row_version','updated_at'] OR
    EXISTS(SELECT 1 FROM jsonb_object_keys(event_row) key WHERE NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.shift_close_events'::regclass AND attname=key AND attnum>0 AND NOT attisdropped)) OR
    (event_row->>'id')::uuid IS DISTINCT FROM (payload->>'eventId')::uuid OR (event_row->>'shift_id')::uuid IS DISTINCT FROM v_shift OR
    lower(btrim(event_row->>'store_id')) IS DISTINCT FROM lower(btrim(p_branch_id)) OR event_row->>'terminal_id' IS DISTINCT FROM p_terminal_id OR
    event_row->>'event' IS DISTINCT FROM 'closing_started' OR event_row->>'from_state' IS DISTINCT FROM 'ACTIVE' OR event_row->>'to_state' IS DISTINCT FROM 'CASH_COUNT_REQUIRED' OR
    event_row->>'actor_staff_id' IS DISTINCT FROM p_closing_start->>'subject' OR event_row->>'actor_name' IS DISTINCT FROM p_closing_start->>'subject' OR
    event_row->>'created_at' IS NULL OR parent->>'closing_started_by' IS DISTINCT FROM p_closing_start->>'subject' OR
    (parent->>'closing_started_at')::timestamptz IS DISTINCT FROM (event_row->>'created_at')::timestamptz OR
    parent->>'close_reason' IS DISTINCT FROM event_row->'detail'->>'reason' OR (parent->>'id')::uuid IS DISTINCT FROM v_shift OR
    lower(btrim(parent->>'store_id')) IS DISTINCT FROM lower(btrim(p_branch_id))
 THEN RAISE EXCEPTION 'SYNC_SHIFT_START_INVALID'; END IF;
 -- Locks share the existing financial writer order. Proof is not a predecessor.
 PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-batch:'||p_batch_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-intent:'||p_batch_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-shift:'||v_shift::text,0));
 SELECT * INTO registered FROM pos_sync_private.shift_author_keys WHERE key_id=(p_closing_start->>'keyId')::uuid AND author_id=(p_closing_start->>'authorId')::uuid
   AND terminal_id=p_terminal_id AND project_origin=p_closing_start->>'projectOrigin' AND subject=p_closing_start->>'subject' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'SYNC_SHIFT_START_INVALID'; END IF;
 SELECT * INTO existing FROM pos_sync_private.shift_closing_start_receipts WHERE intent_id=p_batch_id;
 IF FOUND THEN
  IF existing.proof IS DISTINCT FROM p_closing_start THEN RAISE EXCEPTION 'SYNC_SHIFT_START_HISTORY_UNPROVEN'; END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM pos_sync_private.shift_author_receipts WHERE intent_id=p_batch_id) OR EXISTS(SELECT 1 FROM pos_sync_private.shift_closing_start_receipts WHERE event_id=(p_closing_start->>'eventId')::uuid)
  THEN RAISE EXCEPTION 'SYNC_SHIFT_START_HISTORY_UNPROVEN'; END IF;
  IF p_start_authority->'allowed' IS DISTINCT FROM 'true'::jsonb OR p_start_authority->'authority'->>'authorId' IS DISTINCT FROM registered.author_id::text OR registered.revoked_at IS NOT NULL
  THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_PERMISSION_REVOKED'; END IF;
  SELECT * INTO person FROM public.app_users WHERE id=registered.author_id FOR SHARE;
  IF NOT FOUND OR person.is_active IS DISTINCT FROM true OR person.user_id IS DISTINCT FROM registered.subject OR
     (person.store_id IS NOT NULL AND lower(btrim(person.store_id)) IS DISTINCT FROM lower(btrim(p_branch_id))) OR
     NOT pos_sync_private.shift_author_flag(person.permissions,'can_close_shift') OR
     (EXISTS(SELECT 1 FROM public.terminal_tokens WHERE id::text=p_terminal_id AND location_id IS NULL) AND NOT pos_sync_private.shift_author_management_allowed(person.role::text,person.role_slug,person.permissions))
  THEN RAISE EXCEPTION 'SYNC_SHIFT_AUTHOR_PERMISSION_REVOKED'; END IF;
 END IF;
 SELECT count(*) INTO event_count FROM jsonb_array_elements(intent->'operations') op,LATERAL jsonb_array_elements(op->'rows') r
  WHERE op->>'table'='shift_close_events' AND r->>'event'='closing_started';
 IF event_count<>1 THEN RAISE EXCEPTION 'SYNC_SHIFT_START_INVALID'; END IF;
 SELECT r INTO old_event FROM jsonb_array_elements(intent->'operations') op,LATERAL jsonb_array_elements(op->'rows') r WHERE op->>'table'='shift_close_events' AND r->>'event'='closing_started';
 IF (to_jsonb(jsonb_populate_record(NULL::public.shift_close_events,old_event))-'row_version'-'updated_at') IS DISTINCT FROM
    (to_jsonb(jsonb_populate_record(NULL::public.shift_close_events,event_row))-'row_version'-'updated_at') THEN RAISE EXCEPTION 'SYNC_SHIFT_START_INVALID'; END IF;
 SELECT r INTO final_parent FROM jsonb_array_elements(intent->'operations') op,LATERAL jsonb_array_elements(op->'rows') r WHERE op->>'table'='shifts' AND (r->>'id')::uuid=v_shift;
 IF final_parent IS NULL THEN RAISE EXCEPTION 'SYNC_SHIFT_START_INVALID'; END IF;
 -- The freezer can preserve accepted cloud opening microseconds, while Main's
 -- actual parent postimage has SQL Server millisecond precision. Compare that
 -- immutable opening identity at native precision without rewriting either JSON.
 IF date_trunc('milliseconds',(parent->>'opened_at')::timestamptz) IS DISTINCT FROM date_trunc('milliseconds',(final_parent->>'opened_at')::timestamptz)
 THEN RAISE EXCEPTION 'SYNC_SHIFT_START_INVALID'; END IF;
 FOREACH field IN ARRAY ARRAY['id','store_id','terminal_id','opened_by_staff_id','opened_by_name','closing_started_at','closing_started_by','close_reason'] LOOP
  IF (to_jsonb(jsonb_populate_record(NULL::public.shifts,parent))->field) IS DISTINCT FROM (to_jsonb(jsonb_populate_record(NULL::public.shifts,final_parent))->field)
  THEN RAISE EXCEPTION 'SYNC_SHIFT_START_INVALID'; END IF;
 END LOOP;
 SELECT * INTO cloud_parent FROM public.shifts WHERE id=v_shift FOR SHARE;
 -- Preserve the original opening terminal, including historical NULL, against
 -- the locked cloud record and the already-compared final signed parent. The
 -- actual starter/event/key and counter remain bound to p_terminal_id above.
 IF NOT FOUND OR cloud_parent.store_id IS DISTINCT FROM p_branch_id OR cloud_parent.terminal_id IS DISTINCT FROM parent->>'terminal_id' OR
    date_trunc('milliseconds',cloud_parent.opened_at) IS DISTINCT FROM date_trunc('milliseconds',(parent->>'opened_at')::timestamptz) OR
    cloud_parent.opened_by_staff_id IS DISTINCT FROM parent->>'opened_by_staff_id' OR cloud_parent.opened_by_name IS DISTINCT FROM parent->>'opened_by_name'
 THEN RAISE EXCEPTION 'SYNC_SHIFT_START_INVALID'; END IF;
 previous_context:=current_setting('pos.shift_closing_start',true);
 PERFORM set_config('pos.shift_closing_start',jsonb_build_object('intentId',p_batch_id,'proof',p_closing_start)::text,true);
 result:=public.pos_sync_push_author_shift_intent(p_batch_id,p_organization_id,p_branch_id,p_terminal_id,p_operations,p_shift_intent,p_shift_author,p_author_authority);
 IF existing.intent_id IS NULL THEN
  INSERT INTO pos_sync_private.shift_closing_start_receipts(intent_id,event_id,key_id,author_id,proof) VALUES(p_batch_id,(p_closing_start->>'eventId')::uuid,registered.key_id,registered.author_id,p_closing_start);
 END IF;
 PERFORM set_config('pos.shift_closing_start',COALESCE(previous_context,''),true);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.sale_refund(_sale_id uuid, _lines jsonb DEFAULT NULL::jsonb, _client_refund_id text DEFAULT NULL::text, _reason text DEFAULT NULL::text, _branch_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  _sale public.sales%ROWTYPE;
  _key text := coalesce(nullif(btrim(coalesce(_client_refund_id, '')), ''), _sale_id::text);
  _item record;
  _want integer;
  _remaining integer;
  _movement uuid;
  _stock integer;
  _results jsonb := '[]'::jsonb;
  _outstanding integer;
  _direct boolean := auth.uid() IS NOT NULL;
BEGIN
  -- A direct caller must be staff with the refund permission. A call with no
  -- signed-in user can only come from the trusted server relay, which has
  -- already proved the caller, their branch and their permission.
  IF _direct THEN
    IF NOT public.is_staff_now() THEN
      RAISE EXCEPTION 'Sign in with a staff account to process a refund';
    END IF;
    IF NOT public.has_perm('can_process_refund') THEN
      RAISE EXCEPTION 'You are not allowed to process refunds';
    END IF;
  END IF;

  SELECT * INTO _sale FROM public.sales WHERE id = _sale_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unknown bill';
  END IF;
  IF nullif(btrim(_branch_id), '') IS NOT NULL AND _branch_id <> _sale.store_id THEN
    RAISE EXCEPTION 'The refund must belong to the specified branch';
  END IF;
  IF _direct AND NOT public.user_has_store_access(_sale.store_id) THEN
    RAISE EXCEPTION 'You can only refund bills from your own branch';
  END IF;

  PERFORM set_config('pos.refunding', 'on', true);

  FOR _item IN
    SELECT si.id, si.product_id, si.quantity, si.refunded_qty
      FROM public.sale_items si
     WHERE si.sale_id = _sale_id
     ORDER BY si.id
     FOR UPDATE
  LOOP
    IF _lines IS NULL OR jsonb_array_length(_lines) = 0 THEN
      _want := GREATEST(_item.quantity, 0) - _item.refunded_qty;
    ELSE
      SELECT COALESCE(SUM(GREATEST((l ->> 'qty')::int, 0)), 0) INTO _want
        FROM jsonb_array_elements(_lines) l
       WHERE (l ->> 'item_id') = _item.id::text
          OR ((l ->> 'item_id') IS NULL AND (l ->> 'product_id') = _item.product_id::text);
    END IF;

    CONTINUE WHEN coalesce(_want, 0) <= 0;

    _remaining := GREATEST(_item.quantity, 0) - _item.refunded_qty;
    IF _want > _remaining THEN
      RAISE EXCEPTION 'Cannot return % of "%": only % left to return',
        _want, _item.product_id, _remaining;
    END IF;

    UPDATE public.sale_items
       SET refunded_qty = refunded_qty + _want
     WHERE id = _item.id;

    _movement := md5(_key || ':' || _item.id::text)::uuid;
    _stock := public.stock_apply_delta(_movement, _item.product_id, _sale.store_id, _want);
    _results := _results || jsonb_build_object(
      'item_id', _item.id,
      'product_id', _item.product_id,
      'qty', _want,
      'stock', _stock
    );
  END LOOP;

  SELECT COALESCE(SUM(GREATEST(si.quantity, 0) - si.refunded_qty), 0) INTO _outstanding
    FROM public.sale_items si WHERE si.sale_id = _sale_id;

  IF _outstanding = 0 THEN
    UPDATE public.sales
       SET is_refunded = true, updated_by = coalesce(auth.uid()::text, updated_by)
     WHERE id = _sale_id AND coalesce(is_refunded, false) = false;
  END IF;

  BEGIN
    INSERT INTO public.audit_logs (action, entity_type, entity_id, user_id, details)
    VALUES ('sale_refund', 'sale', _sale_id::text, auth.uid(),
            jsonb_build_object('reason', _reason, 'lines', _results, 'refund_id', _key));
  EXCEPTION WHEN others THEN
    NULL;
  END;

  PERFORM set_config('pos.refunding', 'off', true);

  RETURN jsonb_build_object(
    'sale_id', _sale_id,
    'fully_refunded', _outstanding = 0,
    'lines', _results
  );
END;
$function$
